import{_ as a,o,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Matrice manuale — applicazioni in una vista nativa (M18, traccia E)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m18-webview-matrice.md","filePath":"qa/m18-webview-matrice.md"}'),d={name:"qa/m18-webview-matrice.md"};function n(r,e,l,c,s,p){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="matrice-manuale-—-applicazioni-in-una-vista-nativa-m18-traccia-e" tabindex="-1">Matrice manuale — applicazioni in una vista nativa (M18, traccia E) <a class="header-anchor" href="#matrice-manuale-—-applicazioni-in-una-vista-nativa-m18-traccia-e" aria-label="Permalink to &quot;Matrice manuale — applicazioni in una vista nativa (M18, traccia E)&quot;">​</a></h1><p>Da eseguire a mano, con la finestra vera del client desktop, prima di accendere per default <code>features.web_viewer</code> (<a href="./../adr/0056-applicazioni-in-vista-nativa.html">ADR-0056</a>, accettato il 2026-11-15; per la 1.7.1 l&#39;owner ha deciso di lasciare il flag spento; <strong>in M21 l&#39;owner lo ha acceso di default</strong>, <a href="./../adr/0060-web-viewer-acceso-di-default.html">ADR-0060</a>, quindi questa matrice resta da eseguire con la funzione già visibile a tutti). <strong>In M22 la vista integrata è accesa anche su Windows e su Linux</strong> (<a href="./../adr/0062-vista-integrata-windows-linux.html">ADR-0062</a>, accettato il 2026-11-20): le sezioni 2 e 3 provano i due driver, con il ripiego e l&#39;interruttore <code>CLARAE_WEBVIEW=off</code>. Le prove automatiche non vedono la vista nativa: qui si verifica ciò che solo una finestra reale mostra. <strong>Come prepararle, in che ordine eseguirle e dove registrare gli esiti:</strong> il runbook <a href="./verifica-manuale-1.7.html"><code>verifica-manuale-1.7.md</code></a>.</p><p><strong>Stato al 2026-11-19: nessun caso di questa matrice è stato eseguito</strong> (la sezione 1 è del 2026-11-15; le sezioni 2 e 3 sono state riscritte il 2026-11-19 per M22). La colonna «Esito» è vuota di proposito. Per ogni caso si scrive l&#39;esito (<code>ok</code>, <code>ko</code> con una riga sul difetto e il suo livello P0, P1, P2, oppure <code>n/d</code>), con data, sistema operativo e versione provata, nel registro in fondo.</p><h2 id="cosa-e-gia-coperto-da-prove-automatiche-e-cosa-no" tabindex="-1">Cosa è già coperto da prove automatiche e cosa no <a class="header-anchor" href="#cosa-e-gia-coperto-da-prove-automatiche-e-cosa-no" aria-label="Permalink to &quot;Cosa è già coperto da prove automatiche e cosa no&quot;">​</a></h2><p><strong>Coperto (non va ripetuto a mano, salvo dubbio):</strong></p><ul><li><strong>Il core Go.</strong> <code>internal/webview</code> (politica di navigazione, regola della rete privata, limiti, acceleratori, gesto dell&#39;utente per le nuove finestre) e <code>internal/app/bindings_webview_test.go</code> (vault, flag, errori), con <code>go test -race</code>; <code>go vet</code> per <code>GOOS=js</code>, <code>GOOS=windows CGO_ENABLED=0</code> (<code>task vet-windows</code>) e <code>GOOS=linux</code> con cgo e il tag <code>gtk3</code> (<code>task vet-linux</code>, in un container Docker). Per la perdita del driver: i test del <code>Manager</code> sul driver finto (<code>TestAPlatformThatCannotShowViewsIsUnavailableForTheSession</code> e gli altri due), <code>TestAPlatformThatCannotShowViewsFallsBackToTheSystemBrowser</code> nel binding e <code>switch_test.go</code> per <code>CLARAE_WEBVIEW</code>.</li><li><strong>Il driver macOS contro una finestra reale</strong>, con <code>task test-nativeview</code> (a mano, su un Mac): 14 prove su 14 su un Mac reale (macOS 27.2.1, arm64): un sito che vieta l&#39;incorniciamento caricato (<code>https://github.com</code>), bounds entro il punto a più dimensioni della finestra, schemi vietati rifiutati, nuove finestre non aperte, download rifiutati, certificato autofirmato rifiutato, richieste di credenziali annullate, scorciatoie riservate, 100 cicli di apertura e chiusura, dati separati per vault e <code>ClearData</code>.</li><li><strong>Il driver Linux contro una finestra vera di Wails su GTK3 sotto Xvfb (X11)</strong>, con <code>task test-nativeview-linux</code> (a mano, in Docker): 14 test (innesto, pagina e user agent, posizione, nulla dell&#39;app raggiungibile, schemi e frame, nuove finestre, download e permessi, certificati, autenticazione, tasti riservati, fuoco e attività, sessioni per vault, store in cancellazione, cicli di apertura, chiusura con le viste aperte), <strong>con la sandbox di WebKit accesa</strong> (il container ha <code>--cap-add SYS_ADMIN --cap-add NET_ADMIN</code> e seccomp e systempaths non confinati; su un Mac arm64 serve <code>LINUX_ARCH=arm64</code>). Riportati verdi su arm64 dagli sviluppatori; l&#39;esito amd64 precedente era senza sandbox e non vale più. <strong>Non</strong> è una prova di Wayland, di una scheda grafica reale né di mouse e tastiera veri.</li><li><strong>Il frontend sul mock dei binding e sul core WASM.</strong> vitest in <code>packages/workbench/src/webapp/</code> (modello, conferma dell&#39;origine, comandi, gestore delle viste, scorciatoie, barra e riquadri), l&#39;e2e <code>apps/desktop/frontend/e2e/webapp.spec.ts</code> (17 casi: creazione, conferma, bounds come frazioni, zoom dell&#39;app, vista nascosta sotto palette, dialogo e menu, trascinamenti, schede non attive, layout ripristinato, riquadro senza browser incorporato, scorciatoie, barra, certificato, <code>clear-data</code>, richieste di rete) e la scansione di accessibilità in <code>a11y.spec.ts</code>. Girano in Chromium, <strong>non vedono la vista nativa</strong>.</li></ul><p><strong>Non coperto (è lo scopo di questa matrice):</strong></p><ul><li>Nulla del <strong>frontend sulla finestra reale del desktop</strong>: il posizionamento della vista sopra l&#39;HTML, i bounds con lo zoom dell&#39;app diverso da 100% (WebKit può rispondere diversamente da Chromium), lo sfarfallio nel nascondere e mostrare, il fuoco da tastiera, la sonda <code>elementsFromPoint</code> su <code>WKWebView</code>, il trascinamento di una scheda sopra la vista.</li><li>Nella prova del driver: tastiera e mouse reali (il processo di prova non è l&#39;applicazione attiva: gli eventi sono costruiti), camera e microfono (in quella configurazione <code>navigator.mediaDevices</code> non esiste), NTLM e certificato client, macOS precedente alla 14, il limite di viste.</li><li><strong>Windows a runtime</strong> (il driver non è mai stato eseguito su Windows) e <strong>Linux su Wayland, con una GPU reale e con input veri</strong>: sono le sezioni 2 e 3. Il ripiego («Apri nel browser» quando il runtime manca) è provato sul driver finto e sul mock, <strong>non</strong> su un sistema che il runtime non ce l&#39;ha.</li></ul><h2 id="come-accendere-la-funzione" tabindex="-1">Come accendere la funzione <a class="header-anchor" href="#come-accendere-la-funzione" aria-label="Permalink to &quot;Come accendere la funzione&quot;">​</a></h2><p>Dalla versione di M21 la funzione è <strong>accesa di default</strong> (<code>features.web_viewer</code> vale <code>true</code> anche senza un profilo: un vault solo locale la vede). Per le prove con il flag <strong>spento</strong> o per provare un profilo di gruppo serve un cloud, con <code>features.web_viewer</code> in un Config Profile. Fino alla 1.7.1 era spenta di default. In sviluppo:</p><ol><li><code>task stack-up</code> (PostgreSQL, S3, Keycloak) e <code>task dev-cloud</code> (cloud su <code>:18081</code>); oppure <code>scripts/run-desktop-with-cloud.sh</code>, che avvia stack, cloud e desktop insieme (<code>--help</code> elenca le opzioni; utenti <code>admin</code>, <code>user1</code>, <code>user2</code>, password <code>clarae-dev-password</code>).</li><li>Nella console web, come <code>admin</code>, nel profilo globale (o in un profilo assegnato a un gruppo di <code>user1</code>) impostare <code>{&quot;features&quot;: {&quot;web_viewer&quot;: true}}</code> (con la versione di M21 non serve: è il default; <code>false</code> la spegne).</li><li>Sul client desktop, collegare il vault al cloud con <code>user1</code> (<em>Impostazioni → Cloud</em>): il profilo arriva al collegamento e a ogni aggiornamento. Con il flag acceso compaiono <em>Nuova applicazione</em> nel ribbon e nello stato vuoto.</li><li>Per i casi sul workbench web: aprire lo stesso vault dalla console del cloud, con lo stesso profilo.</li></ol><p>Per provare <strong>solo il driver macOS</strong>, senza cloud né UI: <code>task test-nativeview</code> (a mano, su un Mac con lo schermo acceso: apre una finestra, non fa parte di <code>task ci</code> e usa la rete per due controlli: un sito che vieta l&#39;incorniciamento, <code>https://github.com</code> o quello in <code>CLARAE_NATIVEVIEW_PUBLIC</code>, e il nome <code>*.localtest.me</code>; un controllo senza rete è segnato come saltato, mai come passato). Stampa un riepilogo finale («LIVE RESULT»).</p><p>Per spegnere la funzione a metà prova: <code>{&quot;features&quot;: {&quot;web_viewer&quot;: false}}</code>; le viste aperte si chiudono (caso M33).</p><p><strong>Per spegnere la vista integrata su un singolo computer Windows o Linux</strong> (ADR-0062): avviare l&#39;app con la variabile d&#39;ambiente <code>CLARAE_WEBVIEW=off</code> (vale solo il valore <code>off</code>, senza badare a maiuscole e spazi; macOS non la legge). Il flag del profilo resta acceso, ma <code>embeddedBrowser</code> è falso e le applicazioni si aprono nel browser di sistema: è il ripiego dei casi W1-W7 e L1-L3. PowerShell: <code>$env:CLARAE_WEBVIEW = &quot;off&quot;</code> e poi <code>clarae.exe</code>; Linux: <code>CLARAE_WEBVIEW=off clarae</code>.</p><p>Per provare <strong>solo il driver Linux</strong>, senza cloud né UI (X11 sotto Xvfb, in Docker): <code>task test-nativeview-linux</code> (vedi sopra). Sui due sistemi, la <strong>cartella dei dati</strong> di un&#39;esecuzione di prova si sceglie con <code>--data-dir</code> (per esempio <code>clarae.exe --data-dir C:\\Prove\\Clarae</code>), e le sessioni delle applicazioni stanno in <code>&lt;cartella dati&gt;/webapps/&lt;store&gt;</code>.</p><h2 id="preparazione" tabindex="-1">Preparazione <a class="header-anchor" href="#preparazione" aria-label="Permalink to &quot;Preparazione&quot;">​</a></h2><ul><li><strong>Applicazioni da registrare</strong> (<em>Nuova applicazione</em>): <code>https://github.com</code> (vieta l&#39;incorniciamento), un secondo sito di propria scelta con un login, e un server locale (per esempio <code>python3 -m http.server 8000</code> e <code>http://localhost:8000</code>).</li><li>Un sito con <strong>certificato autofirmato</strong> (per esempio un server locale HTTPS con un certificato generato a mano).</li><li>Un <strong>vault privato</strong> con il blocco automatico per inattività a 1 minuto (<code>security.vault_lock_minutes</code> nel profilo, o l&#39;impostazione di sicurezza dell&#39;utente).</li><li>Un secondo dispositivo o browser collegato allo stesso vault, per il caso della sincronizzazione.</li></ul><h2 id="_1-macos-vista-incorporata" tabindex="-1">1. macOS (vista incorporata) <a class="header-anchor" href="#_1-macos-vista-incorporata" aria-label="Permalink to &quot;1. macOS (vista incorporata)&quot;">​</a></h2><p>Sistemi: macOS 14 o successivo (caso principale) e macOS 13 (dati non persistenti). Con schermo retina e, se possibile, un secondo schermo non retina.</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>M1</td><td>Sito che vieta l&#39;incorniciamento</td><td><em>Nuova applicazione</em> con <code>https://github.com</code>; alla richiesta «Aprire <a href="https://github.com" target="_blank" rel="noreferrer">https://github.com</a> qui?» scegliere «Apri qui».</td><td>La conferma compare anche per chi ha appena creato l&#39;applicazione. La pagina si carica dentro la scheda, sotto la barra (indietro, avanti, ricarica, indirizzo come testo, «Cambia indirizzo», «Apri nel browser»).</td><td></td></tr><tr><td>M2</td><td>Posizione e dimensione della vista</td><td>Con M1 aperta, confrontare il bordo della pagina con quello del riquadro sotto la barra, nei due temi.</td><td>La pagina riempie il riquadro, senza fessure né sbordi sulla barra, sulla barra laterale o sulla barra di stato.</td><td></td></tr><tr><td>M3</td><td>Palette dei comandi sopra la vista</td><td>Con la pagina a fuoco premere <code>Mod+P</code>; poi <code>Esc</code>.</td><td>La palette si vede <strong>sopra</strong> la pagina (la vista si nasconde) e risponde alla tastiera; chiusa la palette la pagina torna com&#39;era, nello stesso punto.</td><td></td></tr><tr><td>M4</td><td>Selettore rapido sopra la vista</td><td><code>Mod+O</code>, poi <code>Esc</code>. Poi di nuovo <code>Mod+O</code> e digitare parte del nome di un&#39;applicazione registrata.</td><td>Come M3. Dalla 1.7.1 il selettore <strong>elenca le applicazioni</strong> (file <code>.webapp</code>) per nome, insieme a note, lavagne, basi e disegni, con l&#39;icona del tipo; <code>Invio</code> apre la scheda (con la conferma dell&#39;origine alla prima apertura, M1 e M37). Vedi anche M42.</td><td></td></tr><tr><td>M5</td><td>Menu contestuale di una scheda</td><td>Tasto destro sulla scheda dell&#39;applicazione e sulle altre schede.</td><td>Il menu si vede per intero sopra la pagina, comprese le voci che escono dal riquadro; chiuso, la pagina torna.</td><td></td></tr><tr><td>M6</td><td>Dialoghi</td><td><em>Cambia indirizzo</em>; <em>Elimina i dati delle applicazioni</em> (annullare); <em>Nuova applicazione</em>.</td><td>Ogni dialogo (con il suo sfondo) è sopra la pagina e prende il fuoco; chiuso, la pagina torna.</td><td></td></tr><tr><td>M7</td><td>Impostazioni</td><td>Aprire le impostazioni con un&#39;applicazione visibile.</td><td>Le impostazioni si vedono sopra la pagina; chiuse, la pagina torna.</td><td></td></tr><tr><td>M8</td><td>Tooltip</td><td>Fermare il puntatore su un pulsante della barra, e su un elemento della barra laterale che sconfina sul riquadro.</td><td>Il tooltip si legge (la vista non lo copre). <strong>Limite noto:</strong> un overlay molto piccolo e senza sfondo può passare tra i punti della sonda; annotare se capita.</td><td></td></tr><tr><td>M9</td><td>Trascinare una scheda sopra la vista</td><td>Trascinare un&#39;altra scheda sul pannello dell&#39;applicazione, e la scheda dell&#39;applicazione su un altro pannello (anche per dividere il pannello).</td><td>Durante il trascinamento la vista si nasconde e si vede il bersaglio del rilascio; a fine trascinamento la pagina torna. Nessun trascinamento si «perde» dentro la pagina.</td><td></td></tr><tr><td>M10</td><td>Trascinare uno splitter</td><td>Trascinare il divisore tra due pannelli e quello della barra laterale, con un&#39;applicazione visibile.</td><td>La vista si nasconde mentre si trascina e torna al rilascio, con le nuove dimensioni.</td><td></td></tr><tr><td>M11</td><td>Trascinare un file dal Finder</td><td>Trascinare un file dal Finder sopra la finestra, sul riquadro dell&#39;applicazione, e rilasciarlo.</td><td>La vista si nasconde sopra la finestra; il rilascio è gestito dall&#39;app (non dalla pagina); a fine operazione la pagina torna.</td><td></td></tr><tr><td>M12</td><td>Ridimensionare la finestra</td><td>Ridurre e allargare la finestra a mano, anche fino al minimo.</td><td>La vista segue il riquadro senza ritardi visibili né sbordi.</td><td></td></tr><tr><td>M13</td><td>Schermo intero</td><td>Entrare e uscire dallo schermo intero del sistema.</td><td>La vista segue il riquadro nelle due direzioni.</td><td></td></tr><tr><td>M14</td><td>Zoom dell&#39;app diverso da 100%</td><td><em>Impostazioni → Aspetto</em>: zoom 80%, 150%, 200%; con ciascuno guardare il bordo della pagina e ripetere M3.</td><td>La vista coincide con il riquadro a ogni zoom. <strong>Da misurare</strong>: i bounds sono frazioni del viewport e WebKit può rispondere diversamente da Chromium.</td><td></td></tr><tr><td>M15</td><td>Schermo retina e secondo schermo</td><td>Spostare la finestra tra uno schermo retina e uno no; ripetere M2.</td><td>Nessuno scarto di posizione o dimensione.</td><td></td></tr><tr><td>M16</td><td>Due pannelli sulla stessa applicazione</td><td>Dividere il pannello e aprire la stessa applicazione nei due; navigare in una.</td><td>Sono <strong>due viste</strong> indipendenti (due pagine con la loro storia); il fuoco segue il pannello cliccato.</td><td></td></tr><tr><td>M17</td><td>Cambio e chiusura di scheda</td><td>Navigare dentro la pagina, passare a una nota, tornare; poi chiudere la scheda dell&#39;applicazione.</td><td>Al ritorno la pagina è com&#39;era (stessa posizione e stessa storia). Chiusa la scheda, la vista sparisce.</td><td></td></tr><tr><td>M18</td><td>Scheda in secondo piano</td><td>Aprire una pagina con un timer o una chat, passare a un&#39;altra scheda per un minuto, tornare.</td><td>La pagina è intatta. I timer della pagina sono rallentati finché la scheda non è attiva: è <strong>accettato</strong> (decisione del proprietario); annotare solo se la pagina si rompe.</td><td></td></tr><tr><td>M19</td><td>Cambio di vault</td><td>Con un&#39;applicazione aperta, aprire un altro vault dal menu del vault; tornare al primo.</td><td>La vista del primo vault si chiude; tornando, la scheda riapre la pagina (chiedendo la conferma solo se l&#39;origine non è già confermata).</td><td></td></tr><tr><td>M20</td><td>Blocco automatico di un vault privato</td><td>Nel vault privato, con il blocco a 1 minuto: (a) restare un minuto fermi con un&#39;applicazione aperta; (b) lavorare per più di un minuto <strong>dentro</strong> la pagina (clic, tasti).</td><td>(a) Il vault si blocca e la vista si chiude: non resta visibile nessuna pagina del vault bloccato; sbloccando si può riaprire l&#39;applicazione. (b) L&#39;attività dentro la pagina conta come attività: il vault <strong>non</strong> si blocca finché si lavora.</td><td></td></tr><tr><td>M21</td><td>Uscita con viste aperte</td><td>Con due o tre applicazioni aperte, <code>Mod+Q</code>; riavviare.</td><td>L&#39;app esce senza attese né processi orfani (verificare in Monitoraggio Attività). Al riavvio le schede tornano <strong>senza caricare nulla</strong> finché non sono mostrate.</td><td></td></tr><tr><td>M22</td><td><code>Elimina i dati delle applicazioni</code> e conferma</td><td>Fare il login in un sito; eseguire <em>Elimina i dati delle applicazioni</em> e confermare; riaprire l&#39;applicazione.</td><td>Le viste del vault si chiudono («I dati delle applicazioni sono stati eliminati»); la sessione è persa; ogni applicazione <strong>chiede di nuovo la conferma</strong> dell&#39;origine. I file <code>.webapp</code> restano.</td><td></td></tr><tr><td>M23</td><td>Sessione persistente</td><td>Su macOS 14 o successivo: fare il login in un sito, chiudere l&#39;app e riaprirla, riaprire l&#39;applicazione. Provare con un altro vault.</td><td>Nello stesso vault la sessione c&#39;è ancora; <strong>nell&#39;altro vault no</strong> (dati separati per vault). I dati non stanno nella cartella del vault.</td><td></td></tr><tr><td>M24</td><td>Certificato autofirmato</td><td>Registrare un&#39;applicazione su un server con certificato autofirmato e aprirla.</td><td>Riquadro «Il certificato del sito non è valido»; <strong>nessun modo di proseguire</strong>; «Apri nel browser» e «Riprova» ci sono.</td><td></td></tr><tr><td>M25</td><td>Download</td><td>Da una pagina avviare un download (un link a un file <code>.zip</code> o un <code>Content-Disposition: attachment</code>).</td><td>Nessun file scritto; un avviso nella scheda («Un download è stato rifiutato»).</td><td></td></tr><tr><td>M26</td><td>Permessi</td><td>Da una pagina che chiede la camera o il microfono (per esempio una pagina di prova WebRTC su https); poi posizione e notifiche.</td><td>Nessun permesso concesso; un avviso «… ha chiesto il permesso …: negato». Se <code>navigator.mediaDevices</code> non esiste, annotarlo (come nella prova del driver).</td><td></td></tr><tr><td>M27</td><td><code>window.open</code> e <code>target=_blank</code></td><td>Da una pagina: (a) un link <code>target=_blank</code> cliccato a mano; (b) <code>window.open</code> da uno script <strong>senza</strong> clic; (c) lo stesso da una scheda nascosta; (d) molti <code>window.open</code> di fila.</td><td>(a) Nessuna finestra nell&#39;app; l&#39;indirizzo si apre nel <strong>browser di sistema</strong>. (b) e (c) Nulla si apre, solo un avviso. (d) Al massimo un&#39;apertura al secondo.</td><td></td></tr><tr><td>M28</td><td>Pagina che va in crash</td><td>Terminare dal Monitoraggio Attività il processo web della pagina (un processo «WebContent» figlio dell&#39;app).</td><td>Riquadro «La pagina ha smesso di funzionare» con «Riprova» e «Apri nel browser»; «Riprova» ricarica; il resto dell&#39;app non si ferma.</td><td></td></tr><tr><td>M29</td><td>Scorciatoie con il fuoco nella pagina</td><td>Con il fuoco nella pagina premere <code>Mod+W</code>, <code>Mod+P</code>, <code>Mod+O</code>, <code>Mod+[</code>, <code>Mod+]</code>, <code>Mod+R</code>.</td><td>Eseguono il comando <strong>dell&#39;app</strong> (chiude la scheda, apre palette e selettore, indietro, avanti, ricarica), non quello della pagina. Le scorciatoie dell&#39;editor (per esempio <code>Mod+B</code>) restano alla pagina.</td><td></td></tr><tr><td>M30</td><td>Editor a fuoco accanto a un&#39;applicazione</td><td>Due pannelli: una nota a sinistra, un&#39;applicazione a destra; digitare nella nota e usare le sue scorciatoie.</td><td>Il testo e le scorciatoie vanno alla nota, non alla pagina; cliccando la pagina il fuoco passa a lei e il pannello a fuoco cambia.</td><td></td></tr><tr><td>M31</td><td>Schede ripristinate</td><td>Con due applicazioni in due schede (una attiva), chiudere e riaprire l&#39;app.</td><td>Si carica <strong>solo</strong> la scheda mostrata; l&#39;altra carica quando la si attiva.</td><td></td></tr><tr><td>M32</td><td>Limite di 32 viste</td><td>Aprire in schede diverse 32 applicazioni (anche la stessa), poi una 33ª.</td><td>La 33ª mostra «Ci sono troppe applicazioni aperte» con «Apri nel browser» e «Riprova»; chiudendo una scheda e riprovando si apre.</td><td></td></tr><tr><td>M33</td><td>Flag spento a metà</td><td>Con applicazioni aperte, togliere <code>web_viewer</code> dal profilo e attendere l&#39;aggiornamento.</td><td>Le viste si chiudono; le schede passano al riquadro con «Apri nel browser» («Il browser dentro la scheda è disattivato dal profilo di configurazione…»); <em>Nuova applicazione</em> sparisce da ribbon e stato vuoto.</td><td></td></tr><tr><td>M34</td><td>Autenticazione di base</td><td>Aprire un sito che chiede nome utente e password con l&#39;autenticazione HTTP di base.</td><td><strong>Atteso: non funziona.</strong> La richiesta è annullata e la pagina non carica: compare un avviso di navigazione bloccata o l&#39;errore di caricamento; nessuna finestra di credenziali, nessuna password del portachiavi offerta.</td><td></td></tr><tr><td>M35</td><td>Login con popup</td><td>Aprire un sito il cui login si apre in un popup che comunica con <code>window.opener</code>.</td><td><strong>Atteso: non funziona.</strong> Il popup non si apre nell&#39;app: l&#39;indirizzo va al browser di sistema, se c&#39;è stato un clic; il login nella vista non si completa.</td><td></td></tr><tr><td>M36</td><td>Rete privata</td><td>(a) Aprire <code>http://localhost:8000</code>. (b) Da una pagina pubblica, un link verso <code>http://localhost:8000</code> o verso un indirizzo <code>192.168.x.x</code>.</td><td>(a) Si apre (è la scelta dell&#39;utente). (b) La navigazione è bloccata, con un avviso («Una navigazione è stata bloccata»); la pagina resta dov&#39;era.</td><td></td></tr><tr><td>M37</td><td>Applicazione arrivata dalla sync</td><td>Da un altro dispositivo creare un <code>.webapp</code> con un&#39;origine mai usata qui; attendere la sync e aprirlo.</td><td>Compare la conferma «Aprire … qui?» <strong>prima</strong> di caricare qualcosa; «Apri nel browser» è l&#39;alternativa; nulla è stato caricato finché non si conferma.</td><td></td></tr><tr><td>M38</td><td>macOS 13</td><td>Su un Mac con macOS 13: login in un sito, chiudere e riaprire l&#39;app.</td><td>La sessione <strong>non</strong> c&#39;è più (dati non persistenti prima di macOS 14); durante l&#39;esecuzione i cookie funzionano. L&#39;app non avvisa: annotare se serve un avviso. Su macOS 14 o successivo la sessione resta (M23).</td><td></td></tr><tr><td>M39</td><td>Vault in sola lettura</td><td>Aprire un vault condiviso in sola lettura.</td><td><em>Nuova applicazione</em> e <em>Cambia indirizzo</em> sono disabilitati; un&#39;applicazione esistente si apre.</td><td></td></tr><tr><td>M40</td><td>File non valido</td><td>Modificare a mano un <code>.webapp</code> con un indirizzo <code>file:///etc/hosts</code>, poi con JSON rotto.</td><td>Riquadro «Impossibile aprire questa applicazione» con il motivo («Si possono aprire solo indirizzi http e https», «Il file non è un JSON valido») e «Cambia indirizzo»; nessuna vista aperta.</td><td></td></tr><tr><td>M41</td><td>Tastiera e screen reader</td><td>Con VoiceOver: andare alla barra con <code>Tab</code>; leggere avvisi (M25, M26) e riquadri (M24, M28).</td><td>I pulsanti hanno un nome; gli avvisi sono annunciati (<code>aria-live</code>), i riquadri di errore sono <code>alert</code>. <strong>Il contenuto della pagina</strong> non è coperto dall&#39;a11y dell&#39;app: dipende dal sito. Annotare i problemi della barra.</td><td></td></tr><tr><td>M42</td><td>Selettore rapido: tipo e creazione</td><td>Con <code>Mod+O</code> cercare il nome di un&#39;applicazione, di una lavagna, di una base e di un disegno; con VoiceOver ascoltare le voci. Poi digitare il nome di una <strong>nota che non esiste</strong> ma che è anche il nome di una lavagna o di un&#39;applicazione; infine il nome di una nota messa nel cestino (<code>.trash/</code>) e quello di un file in una cartella che inizia per punto.</td><td>Ogni voce ha l&#39;icona del suo tipo e VoiceOver legge nome, tipo e cartella; <code>Invio</code> apre il file nella sua vista, <code>Mod+Invio</code> in una nuova scheda. Il file di un altro tipo con lo stesso nome <strong>non toglie</strong> la voce «Crea…»: la nota si può creare (la tolgono solo una nota, una presentazione <code>.marp</code> o un alias omonimi). I file del cestino e delle cartelle nascoste <strong>non compaiono</strong>. I suggerimenti dei wikilink (<code>[[</code>) restano di sole note e non mostrano le note nel cestino.</td><td></td></tr></tbody></table><h2 id="_2-windows-webview2-acceso-di-default" tabindex="-1">2. Windows (WebView2, acceso di default) <a class="header-anchor" href="#_2-windows-webview2-acceso-di-default" aria-label="Permalink to &quot;2. Windows (WebView2, acceso di default)&quot;">​</a></h2><p>Windows 11 e Windows 10, amd64 e, se disponibile, arm64. Dalla M22 il driver è <strong>acceso senza interruttore</strong>: con il runtime WebView2 dalla versione 1.0.2210.55 la pagina si apre nella scheda; senza, o con <code>CLARAE_WEBVIEW=off</code>, vale il ripiego (<code>embeddedBrowser</code> è falso e l&#39;applicazione si apre nel browser di sistema). <strong>Il driver non è mai stato eseguito su Windows.</strong> <a href="./../adr/0062-vista-integrata-windows-linux.html">ADR-0062</a> e <a href="./../adr/0056-applicazioni-in-vista-nativa.html">ADR-0056</a>, punti 34-36.</p><h3 id="ripiego-vista-spenta-con-clarae-webview-off" tabindex="-1">Ripiego: vista spenta con <code>CLARAE_WEBVIEW=off</code> <a class="header-anchor" href="#ripiego-vista-spenta-con-clarae-webview-off" aria-label="Permalink to &quot;Ripiego: vista spenta con `CLARAE_WEBVIEW=off`&quot;">​</a></h3><p>Eseguire con <code>CLARAE_WEBVIEW=off</code> impostata prima di avviare l&#39;app (stessi casi della 1.7.1, quando il driver era spento).</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>W1</td><td>Creazione</td><td>Con la variabile <code>CLARAE_WEBVIEW=off</code> e il flag acceso: <em>Nuova applicazione</em> da ribbon, da stato vuoto e dalla palette, con <code>https://github.com</code>.</td><td>Si crea il file <code>.webapp</code> e si apre in una scheda.</td><td></td></tr><tr><td>W2</td><td>Riquadro con il pulsante</td><td>Guardare la scheda.</td><td>Riquadro con nome, indirizzo e «Questa applicazione si apre nel browser: il browser dentro la scheda non è disponibile qui.»; pulsante <strong>«Apri nel browser»</strong>. <strong>Nessuna</strong> richiesta di conferma dell&#39;origine (la pagina non si carica nell&#39;app).</td><td></td></tr><tr><td>W3</td><td>Apri nel browser</td><td>Cliccare «Apri nel browser».</td><td>L&#39;indirizzo si apre nel browser predefinito del sistema.</td><td></td></tr><tr><td>W4</td><td>Comandi di navigazione</td><td>Aprire la palette con la scheda dell&#39;applicazione in primo piano.</td><td><em>Applicazione: indietro/avanti/ricarica</em> e <em>Elimina i dati delle applicazioni</em> <strong>non compaiono</strong>; restano <em>Nuova applicazione</em>, <em>Apri applicazione…</em>, <em>Cambia l&#39;indirizzo…</em> e <em>Apri l&#39;applicazione nel browser</em>. <code>Mod+[</code>, <code>Mod+]</code>, <code>Mod+R</code> non eseguono i comandi dell&#39;applicazione (annotare se <code>Ctrl+R</code> ricarica l&#39;intera app).</td><td></td></tr><tr><td>W5</td><td>Flag spento</td><td>Togliere il flag dal profilo.</td><td><em>Nuova applicazione</em> sparisce da ribbon e stato vuoto; un <code>.webapp</code> già presente si apre ancora come riquadro con «Apri nel browser».</td><td></td></tr><tr><td>W6</td><td>File non valido</td><td>Come M40.</td><td>Come M40.</td><td></td></tr><tr><td>W7</td><td>Applicazione dalla sync</td><td>Come M37.</td><td>Nessuna conferma (nulla si carica nell&#39;app); il riquadro offre «Apri nel browser».</td><td></td></tr></tbody></table><h3 id="driver-acceso-senza-interruttore" tabindex="-1">Driver acceso (senza interruttore) <a class="header-anchor" href="#driver-acceso-senza-interruttore" aria-label="Permalink to &quot;Driver acceso (senza interruttore)&quot;">​</a></h3><p>Il driver è una copia ridotta e corretta del binding WebView2 interno di Wails v3.1.0 (<code>webview2/</code>, con <code>LICENSE</code> e <code>NOTICE</code>), compilata per amd64 e arm64 (<code>task vet-windows</code>). <strong>Si accende da solo</strong> se la macchina ha il runtime; non c&#39;è una variabile per accenderlo (<code>CLARAE_WEBVIEW2_EXPERIMENTAL</code> della 1.7.1 non è più letta). Con il runtime mancante <code>New</code> restituisce <code>nil</code> (controllo <code>loader.RuntimeInstalled()</code>) e la capability <code>embeddedBrowser</code> è falsa fin dall&#39;avvio.</p><p><strong>Differenze dichiarate rispetto a macOS</strong> (da tenere presenti nei casi): lo user agent è quello di Edge, non simile a Safari; il selettore di file non si può negare; per il blocco automatico di un vault privato contano solo i tasti e il fuoco, non il mouse né la rotella; il gesto dell&#39;utente per le nuove finestre viene da <code>IsUserInitiated</code>; l&#39;autenticazione integrata di Windows (NTLM, Kerberos) è gestita dal runtime e non dal driver; i dati stanno in <code>&lt;cartella dati&gt;\\webapps\\&lt;store&gt;</code>; il runtime WebView2 deve essere almeno 1.0.2210.55, altrimenti la vista non si apre e la pagina va al browser di sistema.</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>WE1</td><td>Primo avvio con il runtime</td><td>Avviare l&#39;app <strong>senza variabili</strong> su una macchina con il runtime WebView2 aggiornato; aprire <code>https://github.com</code> e confermare l&#39;origine.</td><td>La pagina si carica dentro la scheda, sotto la barra; nessun errore nel log.</td><td></td></tr><tr><td>WE2</td><td>Primo avvio senza il runtime</td><td>Come WE1 su una macchina senza il runtime WebView2 (o con il runtime disinstallato). Aprire poi una seconda applicazione.</td><td>L&#39;app si avvia normalmente; <code>embeddedBrowser</code> è falso (i comandi di navigazione non compaiono); entrambe le applicazioni mostrano il riquadro «Apri nel browser», <strong>senza errori</strong> né finestre di dialogo. Annotare che cosa dice il log.</td><td></td></tr><tr><td>WE3</td><td>Runtime vecchio</td><td>Come WE1 con un runtime più vecchio di 1.0.2210.55 (se il caricatore lo accetta; altrimenti equivale a WE2). Aprire una seconda applicazione.</td><td>La prima apertura non crea la vista e mostra il riquadro «Apri nel browser» (non un errore di caricamento); <strong>per il resto della sessione</strong> le applicazioni mostrano subito il riquadro e <code>embeddedBrowser</code> è falso; il log ha <strong>una sola</strong> riga «native web views are not available on this system». Nessun crash.</td><td></td></tr><tr><td>WE4</td><td><code>webview:state</code>: indirizzo e titolo</td><td>Navigare in una pagina con un titolo e cambiare pagina con un link.</td><td>L&#39;indirizzo mostrato nella barra e il titolo sono quelli della pagina corrente, non vuoti né alterati (nello spike i getter di stringa erano rotti).</td><td></td></tr><tr><td>WE5</td><td>Bounds a più DPI</td><td>Con scala dello schermo al 100, 125, 150 e 200%: confrontare il bordo della pagina con il riquadro (come M2); massimizzare, minimizzare e ripristinare la finestra; con due monitor di DPI diverso spostare la finestra; su arm64 ripetere (<code>PutBounds</code>).</td><td>La pagina coincide con il riquadro a ogni scala, senza fessure né sbordi; dopo minimizza e ripristina torna al suo posto; nessuno scarto cambiando monitor.</td><td></td></tr><tr><td>WE6</td><td>Ordine di sovrapposizione e visibilità</td><td>Come M3…M9: palette, selettore, menu di una scheda, dialoghi, impostazioni, tooltip e trascinamento di una scheda sopra la pagina.</td><td>La vista si nasconde (<code>SetVisible(false)</code>) quando qualcosa dell&#39;app è sopra e torna dopo; nessuna vista copre un dialogo.</td><td></td></tr><tr><td>WE7</td><td>Politica di navigazione</td><td>Aprire <code>http</code> e <code>https</code>; da una pagina pubblica seguire un link verso <code>localhost</code> e un redirect verso la rete privata; registrare o seguire <code>javascript:</code>, <code>file:</code>, <code>ms-settings:</code> ed <code>edge://</code>; aprire una pagina che costruisce frame <code>about:</code>, <code>blob:</code> e <code>data:</code>.</td><td><code>http</code> e <code>https</code> si aprono; il redirect verso la rete privata, <code>javascript:</code>, <code>file:</code>, <code>ms-settings:</code> ed <code>edge://</code> sono rifiutati con l&#39;avviso di navigazione bloccata (come M36 e M40); i frame <code>about:</code>, <code>blob:</code> e <code>data:</code> dentro la pagina funzionano.</td><td></td></tr><tr><td>WE8</td><td>Sito che vieta l&#39;incorniciamento</td><td>Aprire un sito con <code>X-Frame-Options: DENY</code> (<code>https://github.com</code>).</td><td>Si carica nella vista, come M1.</td><td></td></tr><tr><td>WE9</td><td>Nessun canale verso l&#39;app</td><td>Da una pagina di prova locale controllare <code>window.chrome.webview</code> (compreso <code>postMessage</code>), <code>hostObjects</code>, il bridge di Wails e una richiesta a <code>wails.localhost</code>.</td><td><code>chrome.webview.postMessage</code> e <code>hostObjects</code> assenti o inerti, il bridge di Wails assente, <code>wails.localhost</code> irraggiungibile: la pagina non ha alcun modo di parlare con l&#39;app.</td><td></td></tr><tr><td>WE10</td><td><code>window.open</code> e <code>target=_blank</code></td><td>Come M27, (a)…(d).</td><td>Come M27: nessuna finestra nell&#39;app; l&#39;indirizzo va al browser di sistema solo dopo un gesto dell&#39;utente, mai da una vista nascosta, al massimo uno al secondo.</td><td></td></tr><tr><td>WE11</td><td>Download</td><td>Come M25.</td><td>Download annullati: nessun file scritto, un avviso nella scheda.</td><td></td></tr><tr><td>WE12</td><td>Permessi</td><td>Come M26.</td><td>Nessun permesso concesso, un avviso per ciascuno.</td><td></td></tr><tr><td>WE13</td><td>Certificati e credenziali</td><td>Aprire un sito con certificato scaduto, uno con il nome sbagliato e uno autofirmato; poi un sito che chiede un certificato client, uno con autenticazione Basic e uno con NTLM (in un dominio).</td><td>Per i certificati: riquadro di errore e <strong>nessuna via per procedere</strong> (come M24). Certificato client e Basic: annullati, la pagina non carica (come M34). <strong>NTLM: annotare</strong> che cosa accade, la gestione è del runtime.</td><td></td></tr><tr><td>WE14</td><td>Dialoghi JavaScript</td><td>Da una pagina di prova chiamare <code>alert</code>, <code>confirm</code> e <code>prompt</code>.</td><td>Nessuna finestra di dialogo della pagina compare. Annotare i valori che la pagina riceve (su macOS <code>alert</code> è confermato, <code>confirm</code> risponde no, <code>prompt</code> non risponde nulla).</td><td></td></tr><tr><td>WE15</td><td>Funzioni del browser inerti</td><td>Con il fuoco nella pagina: tasto destro, <code>F12</code>, <code>Ctrl+Maiusc+I</code>, <code>Ctrl+P</code>, <code>Ctrl+S</code>, <code>Ctrl+F</code>, <code>F5</code>, zoom (<code>Ctrl+rotella</code>, <code>Ctrl++</code>, <code>Ctrl+-</code>); compilare un modulo con nome e password.</td><td>Nessuna reazione del browser: niente menu contestuale, strumenti di sviluppo, stampa, salvataggio, ricerca, ricarica né zoom; nessun suggerimento di compilazione né gestore di password.</td><td></td></tr><tr><td>WE16</td><td>Scorciatoie riservate</td><td>Con il fuoco nella pagina: <code>Ctrl+W</code>, <code>Ctrl+Maiusc+Tab</code>, i tasti funzione riservati, la punteggiatura (<code>Ctrl+[</code>, <code>Ctrl+]</code>) con layout italiano e tedesco, <code>AltGr</code> con un carattere; poi <code>Ctrl+C</code>, <code>Ctrl+V</code>, <code>Ctrl+X</code>, <code>Ctrl+A</code>, <code>Ctrl+Z</code>.</td><td>Le scorciatoie riservate eseguono il comando <strong>dell&#39;app</strong>, come M29; <code>AltGr</code> non fa scattare scorciatoie; <code>Ctrl+C/V/X/A/Z</code> restano <strong>sempre</strong> alla pagina.</td><td></td></tr><tr><td>WE17</td><td>Fuoco</td><td>Come M30: una nota e un&#39;applicazione in due pannelli; digitare, cliccare, cambiare pannello.</td><td>Il testo e le scorciatoie vanno al pannello a fuoco; cliccando la pagina il fuoco passa a lei.</td><td></td></tr><tr><td>WE18</td><td>Blocco automatico con la sola rotella</td><td>Vault privato con blocco a 1 minuto: (a) per più di un minuto solo mouse e rotella nella pagina; (b) per più di un minuto digitare nella pagina.</td><td><strong>Differenza dichiarata:</strong> (a) il vault <strong>si blocca</strong> e la vista si chiude (mouse e rotella non contano come attività); (b) i tasti contano e il vault non si blocca. Annotare l&#39;esito di (a): è un limite noto, non un difetto in sé.</td><td></td></tr><tr><td>WE19</td><td>Persistenza e separazione per vault</td><td>Come M23: login in un sito, chiudere e riaprire l&#39;app, riaprire l&#39;applicazione; poi lo stesso sito da un altro vault.</td><td>Nello stesso vault la sessione c&#39;è ancora, nell&#39;altro no; i dati stanno in <code>&lt;cartella dati&gt;\\webapps\\&lt;store&gt;</code>, uno per vault, non nella cartella del vault.</td><td></td></tr><tr><td>WE20</td><td><code>app:clear-data</code> e pulizia</td><td>Come M22; poi, con un vault eliminato fuori dall&#39;app e aperto l&#39;ultima volta più di 30 giorni prima (si può simulare cambiando <code>last_opened_at</code> in <code>app.db</code>), riavviare l&#39;app e attendere.</td><td>Come M22, e la cartella dello store del vault sparisce da <code>webapps\\</code>. <strong>(non provato)</strong> la simulazione della data. Un vault solo chiuso, su un disco non montato o in un punto di mount non montato (cartella madre vuota) <strong>non</strong> perde i dati.</td><td></td></tr><tr><td>WE21</td><td>Cicli, limite e uscita</td><td>200 aperture e chiusure di un&#39;applicazione; 32 viste e una 33ª; chiudere la scheda, bloccare il vault privato, uscire dall&#39;app; guardare Gestione attività.</td><td>Nessun crash né crescita di memoria; la 33ª mostra «Ci sono troppe applicazioni aperte» (M32); a chiusura e uscita <strong>nessun processo <code>msedgewebview2.exe</code> orfano</strong>.</td><td></td></tr><tr><td>WE22</td><td>Crash del processo di rendering</td><td>Terminare da Gestione attività il processo <code>msedgewebview2.exe</code> del renderer della pagina.</td><td>Riquadro «La pagina ha smesso di funzionare» con «Riprova» e «Apri nel browser» (come M28); il resto dell&#39;app non si ferma.</td><td></td></tr><tr><td>WE23</td><td>Seconda istanza</td><td>Con applicazioni aperte, avviare una seconda istanza dell&#39;app.</td><td>La seconda istanza non rompe le viste né la cartella dei dati della prima (single-instance). Annotare che cosa accade.</td><td></td></tr><tr><td>WE24</td><td>Valori di <code>CLARAE_WEBVIEW</code></td><td>Avviare con <code>CLARAE_WEBVIEW</code> uguale a <code>&quot;&quot;</code> (vuota), <code>0</code>, <code>false</code>, <code>on</code>, <code>off</code>, <code>OFF</code> e <code>off</code> (con spazi). Poi con la variabile <code>CLARAE_WEBVIEW2_EXPERIMENTAL=1</code> e nient&#39;altro.</td><td><strong>Solo <code>off</code></strong> (qualunque maiuscola, spazi ai lati ignorati) spegne: con <code>off</code> l&#39;applicazione si apre nel browser di sistema e <code>embeddedBrowser</code> è falso; con gli altri valori la vista è incorporata. <code>CLARAE_WEBVIEW2_EXPERIMENTAL</code> non ha <strong>nessun effetto</strong>.</td><td></td></tr><tr><td>WE25</td><td>Sistemi e architetture</td><td>Ripetere WE1, WE5, WE7 e WE21 su Windows 10 e su Windows 11, su amd64 e su arm64.</td><td>Come nei casi richiamati, su ogni combinazione disponibile; <code>n/d</code> con il motivo per le altre.</td><td></td></tr></tbody></table><p>Un esito verde di questi casi dice che il driver di Windows è provato. Un difetto che non fa fallire la creazione della vista (posizione, fuoco, sfarfallio) non è coperto dal ripiego: annotarlo con il suo livello.</p><h2 id="_3-linux-webkitgtk-acceso-di-default" tabindex="-1">3. Linux (WebKitGTK, acceso di default) <a class="header-anchor" href="#_3-linux-webkitgtk-acceso-di-default" aria-label="Permalink to &quot;3. Linux (WebKitGTK, acceso di default)&quot;">​</a></h2><p>Ubuntu 22.04 e 24.04, desktop GNOME su <strong>Wayland</strong> e su <strong>X11</strong>, con una <strong>scheda grafica reale</strong>; amd64 (e arm64 se disponibile). Dalla M22 c&#39;è un driver per la build <code>-tags production,gtk3</code> (il pacchetto ufficiale <code>.deb</code> e l&#39;AppImage): una <code>WebKitWebView</code> in un <code>GtkOverlay</code> che prende il posto della web view di Wails. <strong>Requisiti:</strong> <code>webkit2gtk-4.1</code> dalla versione <strong>2.40</strong> e <strong>bubblewrap (<code>bwrap</code>) funzionante</strong> (la sandbox di WebKit è obbligatoria); sotto, senza <code>bwrap</code>, con la variabile <code>WEBKIT_DISABLE_SANDBOX_THIS_IS_DANGEROUS</code> impostata, o con una build GTK 4, senza cgo o con <code>purego</code>, vale il ripiego. <strong>Il driver è stato provato solo sotto Xvfb (X11) con <code>task test-nativeview-linux</code>; non è mai stato eseguito su un desktop vero.</strong> <a href="./../adr/0062-vista-integrata-windows-linux.html">ADR-0062</a>.</p><p><strong>Differenze dichiarate</strong> (da tenere presenti nei casi): lo user agent è quello di WebKitGTK (finisce in <code>Safari/605.1.15</code>, senza <code>Version/…</code>); il selettore di file è annullato e segnalato (come su macOS); il frame di una navigazione è <strong>in parte sconosciuto</strong> (<code>about:</code>, <code>blob:</code> e <code>data:</code> sono frame; il resto è <code>FrameUnknown</code> e si giudica con le regole del frame principale, senza spostare ciò che il core sa del frame principale; un iframe verso un indirizzo locale da una pagina pubblica è rifiutato, un redirect verso un indirizzo locale dopo una navigazione verso un host pubblico pure); le variabili <code>WEBKIT_*</code> dell&#39;ambiente sono rispettate; i dati stanno in <code>&lt;cartella dati&gt;/webapps/&lt;store&gt;/{data,cache}</code> (cookie in <code>cookies.sqlite</code>), e il contesto di un vault vive fino a <em>Elimina i dati</em> o all&#39;uscita; la posizione delle viste segue il segnale <code>get-child-position</code> dell&#39;overlay.</p><h3 id="ripiego-vista-spenta-con-clarae-webview-off-1" tabindex="-1">Ripiego: vista spenta con <code>CLARAE_WEBVIEW=off</code> <a class="header-anchor" href="#ripiego-vista-spenta-con-clarae-webview-off-1" aria-label="Permalink to &quot;Ripiego: vista spenta con `CLARAE_WEBVIEW=off`&quot;">​</a></h3><p>Con <code>CLARAE_WEBVIEW=off</code> impostata prima di avviare l&#39;app.</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>L1</td><td>Creazione e riquadro con il pulsante</td><td>Come W1 e W2.</td><td>Come W1 e W2.</td><td></td></tr><tr><td>L2</td><td>Apri nel browser</td><td>Cliccare «Apri nel browser».</td><td>L&#39;indirizzo si apre nel browser predefinito; nessun errore nel log.</td><td></td></tr><tr><td>L3</td><td>Comandi di navigazione assenti, flag spento, file</td><td>Come W4, W5 e W6.</td><td>Come W4, W5 e W6.</td><td></td></tr></tbody></table><h3 id="driver-acceso-senza-interruttore-1" tabindex="-1">Driver acceso (senza interruttore) <a class="header-anchor" href="#driver-acceso-senza-interruttore-1" aria-label="Permalink to &quot;Driver acceso (senza interruttore)&quot;">​</a></h3><p>Avviare l&#39;app <strong>senza variabili</strong> (salvo dove indicato). Ogni caso va eseguito su <strong>X11 e su Wayland</strong> (sessione GNOME «Ubuntu on Xorg» e «Ubuntu»), salvo dove si dice altro; annotare nel registro quale.</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>LE1</td><td>Primo avvio, X11</td><td>Su una sessione X11: aprire un vault, <em>Nuova applicazione</em> con <code>https://github.com</code> e confermare l&#39;origine.</td><td>La pagina si carica <strong>dentro la scheda</strong>, sotto la barra (come M1); nessun errore nel log; il resto della finestra (barra dei menu, barre laterali, editor) è invariato.</td><td></td></tr><tr><td>LE2</td><td>Primo avvio, Wayland</td><td>Come LE1 su una sessione Wayland (GNOME). Annotare se l&#39;app gira in Wayland nativo o in XWayland.</td><td>Come LE1. <strong>Annotare</strong> ogni differenza: pagina nera o bianca, vista fuori posto, clic che non arrivano.</td><td></td></tr><tr><td>LE3</td><td>GPU reale e composizione</td><td>Come LE1 con la scheda grafica reale (driver Mesa o proprietario). Se la pagina è nera, riprovare con <code>WEBKIT_DISABLE_COMPOSITING_MODE=1</code> e annotare.</td><td>La pagina si vede e scorre senza strappi. Un difetto che sparisce con la variabile va annotato con il suo livello e con la variabile che lo evita.</td><td></td></tr><tr><td>LE4</td><td>Struttura della finestra</td><td>Con una vista aperta: la barra dei menu (se c&#39;è) resta sopra la pagina; ridimensionare la finestra; aprire e chiudere la barra laterale.</td><td>La vista resta nel riquadro sotto la barra, <strong>senza sbordare né lasciare fessure</strong>, e segue ogni ridimensionamento senza ritardi visibili (la posizione la calcola l&#39;overlay a ogni allocazione).</td><td></td></tr><tr><td>LE5</td><td>Ripiego senza WebKitGTK ≥ 2.40</td><td>Su un sistema con <code>webkit2gtk-4.1</code> più vecchio di 2.40 (se esiste). Aprire due applicazioni.</td><td>L&#39;app si avvia; <code>embeddedBrowser</code> è falso fin dall&#39;avvio; le applicazioni mostrano «Apri nel browser» senza errori. <code>n/d</code> se non si trova un sistema così: il caso è coperto dal test del <code>Manager</code> sul driver finto, non da un sistema reale.</td><td></td></tr><tr><td>LE6</td><td>Innesto che fallisce (ripiego)</td><td>Da una build con un Wails diverso da v3.1.0 (dopo un aggiornamento di Wails): aprire un&#39;applicazione.</td><td>Se il <code>webview-box</code> non c&#39;è, o ha più di una <code>WebKitWebView</code>, la prima apertura mostra «Apri nel browser» (non un crash) e la finestra non è toccata. <code>n/d</code> finché Wails non cambia: ricontrollare a ogni aggiornamento (anche con <code>task test-nativeview-linux</code>).</td><td></td></tr><tr><td>LE7</td><td>Valori di <code>CLARAE_WEBVIEW</code></td><td>Avviare con <code>CLARAE_WEBVIEW</code> uguale a <code>&quot;&quot;</code>, <code>0</code>, <code>false</code>, <code>off</code>, <code>OFF</code> e <code>off</code> (con spazi).</td><td><strong>Solo <code>off</code></strong> (ogni maiuscola, spazi ignorati) spegne: l&#39;applicazione si apre nel browser di sistema e <code>embeddedBrowser</code> è falso; con gli altri valori la vista è incorporata.</td><td></td></tr><tr><td>LE8</td><td>Scala dello schermo e HiDPI</td><td>Con scala 100%, 200% e (su Wayland) 125% e 150% frazionario; due monitor di scala diversa, se disponibili: confrontare il bordo della pagina con il riquadro (come M2) e ripetere LE4.</td><td>La pagina coincide con il riquadro a ogni scala (coordinate logiche, le gestisce GTK); nessuno scarto cambiando monitor.</td><td></td></tr><tr><td>LE9</td><td>Ordine di sovrapposizione e visibilità</td><td>Come M3…M9: palette, selettore, menu di una scheda, dialoghi, impostazioni, tooltip e trascinamento di una scheda sopra la pagina.</td><td>La vista si nasconde quando qualcosa dell&#39;app è sopra e torna dopo; nessuna vista copre un dialogo; i menu nativi (barra dei menu) si vedono sopra la pagina.</td><td></td></tr><tr><td>LE10</td><td>Clic fuori dalla vista</td><td>Con una vista aperta cliccare sulla barra della scheda, sulle barre laterali, sulla barra di stato e sui bordi del pannello; poi nella pagina.</td><td>Ogni clic fuori dalla pagina arriva all&#39;app (nessun «buco» morto); i clic nella pagina vanno alla pagina; il fuoco segue il clic.</td><td></td></tr><tr><td>LE11</td><td>Politica di navigazione e frame</td><td>Come WE7 (<code>http</code>/<code>https</code>; redirect verso la rete privata; <code>javascript:</code>, <code>file:</code>, <code>ftp:</code>, <code>wails:</code>; frame <code>about:</code>, <code>blob:</code>, <code>data:</code>). Poi: una pagina pubblica con un <code>&lt;iframe&gt;</code> verso <code>http://localhost:8000</code>; una pagina locale con un <code>&lt;iframe&gt;</code> verso un sito pubblico.</td><td>Rifiuti come WE7, con l&#39;avviso di navigazione bloccata. <strong>Iframe privato da pagina pubblica: rifiutato.</strong> Nella pagina locale con l&#39;iframe pubblico, un link cliccato verso un altro indirizzo locale <strong>si apre</strong> (l&#39;iframe non cambia ciò che la pagina locale può fare). Vedi anche LE29 e LE30.</td><td></td></tr><tr><td>LE12</td><td>Nessun canale verso l&#39;app</td><td>Da una pagina di prova locale controllare <code>window.wails</code>, <code>window.webkit.messageHandlers</code>, il bridge di Wails e una richiesta a <code>wails://wails/</code>.</td><td><code>window.webkit.messageHandlers</code> assente o senza gestori, il bridge di Wails assente, <code>wails://</code> rifiutato: la pagina non può parlare con l&#39;app.</td><td></td></tr><tr><td>LE13</td><td><code>window.open</code>, download, permessi, file</td><td>Come M27, M25 e M26; poi una pagina con <code>&lt;input type=file&gt;</code> cliccato.</td><td>Come M27, M25 e M26 (nessuna finestra nell&#39;app, download annullato, permessi negati con avviso). <strong>Il selettore di file non compare</strong> (annullato) e un avviso lo dice.</td><td></td></tr><tr><td>LE14</td><td>Certificati e credenziali</td><td>Come WE13 (senza NTLM e certificato client, annullati).</td><td>Certificato scaduto, nome sbagliato o autofirmato: riquadro di errore, <strong>nessuna via per procedere</strong> (come M24); Basic e Digest annullati, la pagina non carica (come M34).</td><td></td></tr><tr><td>LE15</td><td>Dialoghi JavaScript e funzioni del browser</td><td>Come WE14 e WE15 (con <code>Ctrl</code> al posto di <code>Mod</code>).</td><td>Nessuna finestra di dialogo della pagina; nessun menu contestuale con voci per aprire una finestra o scaricare, né strumenti di sviluppo, stampa o schermo intero.</td><td></td></tr><tr><td>LE16</td><td>Scorciatoie riservate</td><td>Con il fuoco nella pagina: <code>Ctrl+W</code>, <code>Ctrl+Maiusc+Tab</code>, <code>Ctrl+P</code>, <code>Ctrl+O</code>, <code>Ctrl+[</code>, <code>Ctrl+]</code>, <code>Ctrl+R</code>; la punteggiatura con layout italiano e tedesco, <code>AltGr</code> con un carattere; il tasto logo con una lettera; poi <code>Ctrl+C</code>, <code>Ctrl+V</code>, <code>Ctrl+X</code>, <code>Ctrl+A</code>, <code>Ctrl+Z</code>.</td><td>Le scorciatoie riservate eseguono il comando <strong>dell&#39;app</strong>, come M29; <code>AltGr</code> e il tasto logo non fanno scattare scorciatoie; <code>Ctrl+C/V/X/A/Z</code> restano <strong>sempre</strong> alla pagina.</td><td></td></tr><tr><td>LE17</td><td>Fuoco</td><td>Come M30: una nota e un&#39;applicazione in due pannelli; digitare, cliccare, cambiare pannello; nascondere la vista (palette) e chiuderla.</td><td>Il testo e le scorciatoie vanno al pannello a fuoco; cliccando la pagina il fuoco passa a lei; nascondendo la vista il fuoco torna alla web view dell&#39;app.</td><td></td></tr><tr><td>LE18</td><td>Blocco automatico con la sola rotella</td><td>Vault privato con blocco a 1 minuto: (a) per più di un minuto solo clic e rotella nella pagina; (b) per più di un minuto digitare nella pagina.</td><td>A differenza di Windows, su Linux contano <strong>tasti, clic e scorrimento</strong> (al più ogni 5 s): il vault <strong>non</strong> si blocca né in (a) né in (b). Annotare ogni blocco inatteso.</td><td></td></tr><tr><td>LE19</td><td>Persistenza e separazione per vault</td><td>Come M23: login in un sito, chiudere e riaprire l&#39;app, riaprire l&#39;applicazione; poi lo stesso sito da un altro vault. Controllare la cartella.</td><td>Nello stesso vault la sessione c&#39;è ancora (su ogni versione), nell&#39;altro no; i dati sono in <code>&lt;cartella dati&gt;/webapps/&lt;store&gt;/{data,cache}</code> (con <code>cookies.sqlite</code>), uno per vault, non nella cartella del vault; i permessi della cartella sono <code>0700</code>.</td><td></td></tr><tr><td>LE20</td><td><code>app:clear-data</code> e pulizia</td><td>Come M22 e WE20 (con la cartella <code>webapps/&lt;store&gt;</code>).</td><td>Come M22; la cartella dello store del vault sparisce da <code>webapps/</code> (può servire qualche secondo: WebKit rilascia prima il contesto). Un vault solo chiuso, su un disco non montato o in un punto di mount non montato <strong>non</strong> perde i dati.</td><td></td></tr><tr><td>LE21</td><td>Cicli, limite e uscita</td><td>200 aperture e chiusure di un&#39;applicazione; 32 viste e una 33ª; chiudere la scheda, bloccare il vault privato, uscire dall&#39;app; guardare i processi (<code>ps</code>).</td><td>Nessun crash né crescita di memoria; la 33ª mostra «Ci sono troppe applicazioni aperte» (M32); a chiusura e uscita <strong>nessun processo <code>WebKitWebProcess</code> o <code>WebKitNetworkProcess</code> orfano</strong>.</td><td></td></tr><tr><td>LE22</td><td>Crash del processo di rendering</td><td>Terminare con <code>kill</code> il <code>WebKitWebProcess</code> della pagina.</td><td>Riquadro «La pagina ha smesso di funzionare» con «Riprova» e «Apri nel browser» (come M28); il resto dell&#39;app non si ferma.</td><td></td></tr><tr><td>LE23</td><td>Seconda istanza</td><td>Con applicazioni aperte, avviare una seconda istanza dell&#39;app.</td><td>La seconda istanza non rompe le viste né la cartella dei dati della prima (single-instance). Annotare che cosa accade.</td><td></td></tr><tr><td>LE24</td><td>User agent</td><td>Da una pagina di prova leggere <code>navigator.userAgent</code>; aprire un sito che sceglie il contenuto in base al browser.</td><td>L&#39;user agent è quello di WebKitGTK, con <code>AppleWebKit</code> e <code>Safari/605.1.15</code>, senza <code>wails</code>; i siti si caricano. Annotare i siti che degradano.</td><td></td></tr><tr><td>LE25</td><td><code>WEBKIT_*</code> dell&#39;ambiente</td><td>Avviare con <code>WEBKIT_DISABLE_COMPOSITING_MODE=1</code>.</td><td>Le variabili sono rispettate (l&#39;app non le imposta né le toglie): la vista funziona come prima o meglio; annotare l&#39;effetto.</td><td></td></tr><tr><td>LE26</td><td>Pacchetti e architetture</td><td>Ripetere LE1, LE4, LE11 e LE21 con il <code>.deb</code> e con l&#39;AppImage, su Ubuntu 22.04 e 24.04, su amd64 (e arm64 se c&#39;è).</td><td>Come nei casi richiamati, su ogni combinazione disponibile; <code>n/d</code> con il motivo per le altre. Con l&#39;AppImage annotare se il sandbox di WebKit (bubblewrap) funziona.</td><td></td></tr><tr><td>LE27</td><td>Senza <code>bwrap</code></td><td>Su un sistema senza bubblewrap (<code>sudo apt remove bubblewrap</code>; attenzione: può togliere altri pacchetti che lo richiedono) o con <code>bwrap</code> fuori dal <code>PATH</code> (<code>PATH</code> ridotto). Aprire due applicazioni.</td><td>L&#39;app si avvia; la prima apertura mostra «Apri nel browser» <strong>senza errori</strong>; <code>embeddedBrowser</code> è falso per il resto della sessione; il log dice che la sandbox non si può avere. <code>n/d</code> se non si può rimuovere <code>bwrap</code>.</td><td></td></tr><tr><td>LE28</td><td>Variabile che disattiva la sandbox</td><td>Avviare con <code>WEBKIT_DISABLE_SANDBOX_THIS_IS_DANGEROUS=1</code> (qualunque valore non vuoto).</td><td>Il driver <strong>non</strong> mostra la pagina: «Apri nel browser» come LE27. L&#39;app non spegne la sandbox per conto suo.</td><td></td></tr><tr><td>LE29</td><td>Flatpak e Snap</td><td>Con un pacchetto Flatpak o Snap dell&#39;app (se esiste; oggi i pacchetti ufficiali sono <code>.deb</code> e AppImage): aprire un&#39;applicazione.</td><td><strong>Non provato.</strong> Annotare uno di tre esiti: la pagina si apre; «Apri nel browser» (la sonda di avvio fallisce, il ripiego funziona); <strong>l&#39;app si chiude</strong> (il processo web non parte dopo una sonda riuscita: rischio residuo noto, <code>g_error</code> di WebKit in <code>readPIDFromPeer</code>), con il messaggio nel log.</td><td></td></tr><tr><td>LE30</td><td>Redirect verso la rete privata</td><td>Un sito pubblico di prova che risponde con un redirect <code>302</code> a <code>http://localhost:8000</code> (e un altro che passa da un host pubblico intermedio: privato → pubblico → privato). Aprire l&#39;URL pubblico.</td><td>Il redirect verso l&#39;indirizzo locale è <strong>rifiutato</strong> con l&#39;avviso di navigazione bloccata; la pagina resta dov&#39;era. Una pagina su un host privato che porta a un altro host privato con un link cliccato dall&#39;utente <strong>si apre</strong>.</td><td></td></tr><tr><td>LE31</td><td>Iframe</td><td>Una pagina pubblica con un <code>&lt;iframe&gt;</code> verso <code>http://localhost:8000</code> e una verso un altro sito pubblico; una pagina locale con un <code>&lt;iframe&gt;</code> pubblico.</td><td>L&#39;iframe privato dalla pagina pubblica non si carica, con l&#39;avviso (segnalato come navigazione non principale); gli iframe pubblici sì; nella pagina locale l&#39;iframe pubblico si carica e i link verso altri indirizzi locali continuano a funzionare.</td><td></td></tr><tr><td>LE32</td><td>Cancellare i dati durante un&#39;apertura</td><td>Aprire un&#39;applicazione di un vault; <em>Elimina i dati delle applicazioni</em> e, <strong>subito</strong>, aprire un&#39;applicazione dello stesso vault.</td><td>Se l&#39;apertura cade durante la cancellazione compare l&#39;errore con «Riprova» (non «Apri nel browser»); «Riprova» dopo qualche secondo apre la pagina; la cartella <code>webapps/&lt;store&gt;</code> è stata cancellata e si ricrea.</td><td></td></tr></tbody></table><p>Un esito verde di questi casi dice che il driver Linux è provato su un desktop vero; un difetto che non fa fallire <code>Create</code> (posizione, fuoco, sfarfallio) non è coperto dal ripiego: annotarlo con il suo livello.</p><h2 id="_4-workbench-web" tabindex="-1">4. Workbench web <a class="header-anchor" href="#_4-workbench-web" aria-label="Permalink to &quot;4. Workbench web&quot;">​</a></h2><p>Un browser con il workbench aperto dalla console del cloud, con il flag acceso nel profilo.</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>B1</td><td>Creazione</td><td><em>Nuova applicazione</em> da ribbon, stato vuoto e palette, con <code>https://github.com</code>.</td><td>Come W1; la creazione, la modifica dell&#39;indirizzo e il selettore sono quelli del desktop.</td><td></td></tr><tr><td>B2</td><td>Scheda del browser</td><td>Aprire l&#39;applicazione e cliccare «Apri nel browser».</td><td>Riquadro come W2 (nessuna conferma dell&#39;origine); il clic apre una <strong>nuova scheda del browser</strong> sull&#39;indirizzo, senza che il blocco dei popup la fermi.</td><td></td></tr><tr><td>B3</td><td>Nessuna vista incorporata</td><td>Nella palette cercare i comandi <em>Applicazione: indietro/avanti/ricarica</em> e <em>Elimina i dati delle applicazioni</em>.</td><td>Non ci sono. Nessuna richiesta di rete verso l&#39;indirizzo dell&#39;applicazione parte dalla pagina del workbench (il pannello <em>Rete</em> degli strumenti del browser), finché non si clicca «Apri nel browser».</td><td></td></tr><tr><td>B4</td><td>Flag spento</td><td>Togliere il flag dal profilo.</td><td><em>Nuova applicazione</em> sparisce; un <code>.webapp</code> presente si apre come riquadro con «Apri nel browser».</td><td></td></tr><tr><td>B5</td><td>File non valido e sola lettura</td><td>Come M40 e M39.</td><td>Come M40 e M39.</td><td></td></tr></tbody></table><h2 id="registro-delle-esecuzioni" tabindex="-1">Registro delle esecuzioni <a class="header-anchor" href="#registro-delle-esecuzioni" aria-label="Permalink to &quot;Registro delle esecuzioni&quot;">​</a></h2><p>Una riga per esecuzione. Un difetto va annotato sotto il caso con il suo livello (P0, P1, P2) e, se blocca l&#39;accensione del flag, riportato in <a href="./../roadmap.html"><code>docs/roadmap.md</code></a> §13-undecies.</p><table tabindex="0"><thead><tr><th>Data</th><th>Sistema operativo e versione</th><th>Versione dell&#39;app</th><th>Esecutore</th><th>Casi eseguiti</th><th>Difetti</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table>',46)])])}const g=a(d,[["render",n]]);export{m as __pageData,g as default};
